function validate([target, types]) {
  if (!Number.isInteger(target) || target < 1 || target > 1000) return 'target is a whole number from 1 to 1000.';
  if (!Array.isArray(types) || types.length < 1 || types.length > 50) return 'types needs 1 to 50 entries.';
  for (const type of types) {
    if (!Array.isArray(type) || type.length !== 2) return 'Each type is a pair [count, marks].';
    if (type.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'count and marks are whole numbers from 1 to 50.';
  }
  return null;
}

