function waysToReachTarget(target, types) {
  const MOD = 1_000_000_007;
  const dp = new Array(target + 1).fill(0);
  dp[0] = 1;
  for (const [count, marks] of types) {
    for (let points = target; points >= 1; points--) {
      for (let solved = 1; solved <= count && solved * marks <= points; solved++) {
        dp[points] = (dp[points] + dp[points - solved * marks]) % MOD;
      }
    }
  }
  return dp[target];
}

