function waysToReachTarget(target, types) {
  const MOD = 1000000007n;
  const memo = new Map();
  // ways(i, left): choices for kinds i.. that add up to exactly `left` points.
  const ways = (i, left) => {
    if (i === types.length) return left === 0 ? 1n : 0n;
    const key = i * 1001 + left;
    if (memo.has(key)) return memo.get(key);
    let total = 0n;
    for (let take = 0; take <= types[i][0] && take * types[i][1] <= left; take++) total += ways(i + 1, left - take * types[i][1]);
    total %= MOD;
    memo.set(key, total);
    return total;
  };
  return Number(ways(0, target));
}

