function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(40, 50);
    return [pick(900, 1000), Array.from({ length: n }, () => [pick(1, 50), pick(1, 50)])];
  }
  const n = pick(1, 4);
  return [pick(1, 20), Array.from({ length: n }, () => [pick(1, 5), pick(1, 6)])];
